-- =====================================================================
-- NETTBUTIKK
--   1) Produktfelt for nettbutikken (merke, kategori, beskrivelser, hold/
--      glans, flere bilder, «passer godt med», før-pris, fremhevet …).
--   2) Produkttekster for alle 143 produkter (skrevet fra produsent/
--      forhandler). Usikre tekster er merket «sjekk teksten» i admin.
--   3) Nettordrer: bestilling, varelinjer, frakt/henting, betaling
--      (Vipps / kort via Vipps / betal ved henting), lager reserveres.
--   4) Kassa: «Utlevert / Sendt» registrerer ordren som salg (regnskap).
--
--   Trygt å kjøre flere ganger. Tekstene fylles bare inn på produkter
--   som ikke har fått nettbutikk-tekst ennå (slug er tom).
-- =====================================================================

-- ---------- 1) Produktfelt ----------
alter table products add column if not exists slug text;
alter table products add column if not exists web_name text;
alter table products add column if not exists brand text;
alter table products add column if not exists category text;
alter table products add column if not exists short_description text;
alter table products add column if not exists benefits text[] not null default '{}';
alter table products add column if not exists recommended_for text;
alter table products add column if not exists how_to_use text;
alter table products add column if not exists ingredients text;
alter table products add column if not exists size_label text;
alter table products add column if not exists hold_level smallint;
alter table products add column if not exists shine_level smallint;
alter table products add column if not exists images text[] not null default '{}';
alter table products add column if not exists related_slugs text[] not null default '{}';
alter table products add column if not exists compare_at_price_nok numeric(10,2);
alter table products add column if not exists featured boolean not null default false;
alter table products add column if not exists online boolean not null default true;
alter table products add column if not exists web_sort int not null default 0;
alter table products add column if not exists content_review boolean not null default false;
alter table products add column if not exists content_note text;
alter table products add column if not exists content_source text;
create unique index if not exists products_slug_uidx on products (slug) where slug is not null;

-- Nettbutikk-innstillinger (frakt, gratis frakt over, hva som er på).
insert into settings (key, value)
values ('webshop', '{"live": false, "shipping_nok": 79, "free_over_nok": 599, "pickup": true, "ship": true, "pay_at_pickup": true}'::jsonb)
on conflict (key) do nothing;

