update products set slug = 'reuzel-the-stache-mustache-wax', brand = 'Reuzel', category = 'Skjegg', short_description = 'Bartvoks med sterkt hold som temmer og former barten, også grov bart.', description = coalesce(nullif(description, ''), 'En bivoksbasert bartvoks som gir sterkt hold, slik at barten holder formen gjennom dagen. Voksen blir myk når du varmer den mellom fingrene og er lett å fordele. Den har en lett duft av appelsinskall og grønn mynte.'), benefits = array['Sterkt hold for formet bart','Bivoksbasert formel','Temmer grov og uregjerlig bart','Lett å varme opp og påføre','Lett duft av appelsin og mynte']::text[], recommended_for = 'Passer for bart som er lang nok til å kammes til siden, og er godt egnet til handlebar og andre formede barter.', how_to_use = 'Ta litt voks på neglen og varm den mellom tommel og pekefinger. Påfør på helt tørr bart fra midten og utover mens du vrir den i form. Vask ut voksen om kvelden.', size_label = '28 g', hold_level = null, shine_level = null, related_slugs = array['beard-monkey-beard-comb']::text[], web_name = null, content_review = true, content_note = 'Fant ingen produktside hos Reuzel; info fra forhandlere (Sweetcare, Laughlin Mercantile, Haarshop.nl). Kilder er uenige om glansen (lav vs. naturlig).', content_source = 'https://www.sweetcare.com/gb/reuzel-the-stache-mustache-wax-p-017858rz'
