update products set slug = 'reuzel-aftershave-original', brand = 'Reuzel', category = 'Barbering', short_description = 'Kjølende aftershave som roer huden og demper irritasjon etter barbering.', description = coalesce(nullif(description, ''), 'Reuzels originale aftershave gir en frisk, kjølende følelse etter barbering og hjelper mot irritasjon. Glyserin holder på fuktigheten, og T-4-blandingen med trollhassel, brennesle, rosmarin og kjerringrokk toner huden. Duften har noter av bergamott, lavendel, neroli og lær.'), benefits = array['Kjøler og friskner opp huden','Demper irritasjon etter barbering','Glyserin mot tørr, stram hud','Klassisk barberduft','Vegansk']::text[], recommended_for = 'Passer for alle som barberer ansikt, hals eller nakke og vil ha en klassisk barbershop-duft.', how_to_use = 'Ha litt i håndflatene og press det inn i nybarbert hud.', size_label = null, hold_level = null, shine_level = null, related_slugs = array['reuzel-shave-cream','derby-5-blades-double-edge']::text[], web_name = null, content_review = false, content_note = 'Finnes i 100 ml og 200 ml; størrelsen kan ikke avgjøres sikkert ut fra prisen.', content_source = 'https://www.reuzel.com/products/after-shave'
