update products set slug = 'reuzel-clay-matte-pomade', brand = 'Reuzel', category = 'Styling', short_description = 'Vannløselig leirepomade med medium, fleksibelt hold og helt matt finish.', description = coalesce(nullif(description, ''), 'En lett pomade med kaolinleire som gir tekstur og definisjon uten glans eller tyngde. Holdet kan bygges opp lag for lag, og frisyren kan formes på nytt med fuktige fingre i løpet av dagen. Den vaskes ut med vanlig sjampo.'), benefits = array['Medium, fleksibelt hold','Matt finish','Kaolinleire som tar opp fett','Kan formes på nytt gjennom dagen','Vaskes lett ut']::text[], recommended_for = 'Passer de fleste hårtyper og særlig fint til medium hår og korte, teksturerte frisyrer.', how_to_use = 'Varm opp en liten mengde i håndflatene og påfør tørt eller håndklærtørt hår fra issen og fremover. Form med fingre eller kam.', size_label = null, hold_level = 3, shine_level = 0, related_slugs = array['reuzel-clay-spray','uppercut-delux-groomin-comb']::text[], web_name = null, content_review = false, content_note = 'Reuzel oppgir i dag 95 g for standardboksen, men eldre/europeisk lager er ofte 113 g – sjekk boksen før størrelse publiseres. Hold/glans omregnet fra Reuzels skala 0–10. Reuzel angir nå holdet som medium (6/10).', content_source = 'https://www.reuzel.com/products/clay-matte-pomade-strong-hold-matte-finish'
