update products set slug = 'uppercut-styling-powder', brand = 'Uppercut Deluxe', category = 'Styling', short_description = 'Ultrafint stylingpudder som gir volum og tekstur med naturlig, matt finish.', description = coalesce(nullif(description, ''), 'Et ultrafint pudder som gir volum og tekstur uten den tyngden en voks eller pomade kan gi. Du styrer holdet med hvor mye du bruker, og frisyren kan formes på nytt gjennom dagen. Fint til crops, teksturerte quiffs og lengre, løse looker.'), benefits = array['Gir volum og tekstur','Justerbart, fleksibelt hold','Naturlig finish uten synlig produkt','Kan formes på nytt','Enkel påføring']::text[], recommended_for = 'Passer alle hårtyper, best til kort og mellomlangt hår – særlig fint eller tynt hår.', how_to_use = 'Rist pudderet over helt tørt hår, rak håret på plass og klyp seksjoner for tekstur. Tilsett mer for mer kontroll.', size_label = '20 g', hold_level = 2, shine_level = 1, related_slugs = array['uppercut-salt-spray','uppercut-clay']::text[], web_name = null, content_review = false, content_note = 'Uppercut beskriver finishen både som matt og naturlig. Uppercut oppgir hold/glans i ord; tallene er omregnet.', content_source = 'https://hk.uppercutdeluxe.com/collections/hair-styling-powder/products/styling-powder'
 where name = 'Uppercut - Styling Powder' and price_nok = 269.0 and slug is null;
update products set slug = 'uppercut-texture-cream', brand = 'Uppercut Deluxe', category = 'Styling', short_description = 'Smidig teksturkrem som ikke stivner og gir naturlig bevegelse og finish.', description = coalesce(nullif(description, ''), 'En stylingkrem som ikke setter seg, men holder seg myk og fleksibel slik at frisyren kan formes på nytt uten mer produkt. Den fremhever tekstur og naturlig bevegelse på både kort og langt hår. Den er vannbasert og har duften «Leather Shadow».'), benefits = array['Smidig, fleksibelt hold','Naturlig finish','Stivner ikke','Kan formes på nytt gjennom dagen','Holdet kan bygges opp']::text[], recommended_for = 'Passer alle hårtyper, fra korte til mellomlange og lengre frisyrer med tekstur og bevegelse.', how_to_use = 'Ta litt i tørre hender, fordel jevnt og rak gjennom tørt hår. Start med lite og bygg opp for mer hold.', size_label = '100 g', hold_level = 3, shine_level = 2, related_slugs = array['uppercut-salt-spray','uppercut-styling-powder']::text[], web_name = null, content_review = false, content_note = 'Uppercut oppgir hold/glans i ord; tallene er omregnet.', content_source = 'https://hk.uppercutdeluxe.com/collections/hair-cream/products/texture-cream'
