update products set slug = 'graabein-beard-balm-lysning', brand = 'Graabein', category = 'Skjegg', short_description = 'Fast skjeggbalm med bivoks og duft av sandeltre og lavendel, for form og hold gjennom dagen.', description = coalesce(nullif(description, ''), 'Lysning er en fast skjeggbalm laget med ekte bivoks, som gir skjegget form og holder det på plass hele dagen. Duften har sandeltre i bunnen og et lett hint av lavendel, og er mildere enn i skjeggoljene. Inneholder sheasmør, bivoks, lanolin og en blanding av oljer som jojoba, argan og mandel. Balmen er fast i romtemperatur og må varmes før bruk.'), benefits = array['Ekte bivoks for sterk styling og hold','Temmer utstående hår','Mild, balansert duft av sandeltre og lavendel','Uten konserveringsmidler','Kan blandes med skjeggolje']::text[], recommended_for = 'For middels til lange skjegg som trenger form og kontroll gjennom dagen.', how_to_use = 'Løsne overflaten med en negl, og varm en liten mengde mellom fingrene i ca. 10 sekunder. Arbeid den inn i skjegget, ikke ned i huden.', size_label = '50 ml', hold_level = null, shine_level = null, related_slugs = array['beard-monkey-beard-comb','graabein-skin-and-beard-softener-villmark']::text[], web_name = null, content_review = false, content_note = null, content_source = 'https://www.graabein-skjegg.no/produkt/graabein-skjeggbalm-lysning'
 where name = 'Graabein - Beard Balm Lysning' and price_nok = 299.0 and slug is null;
update products set slug = 'graabein-beard-balm-mango-coconut', brand = 'Graabein', category = 'Skjegg', short_description = 'Fast skjeggbalm med bivoks og søt duft av mango og kokos, for form og hold hele dagen.', description = coalesce(nullif(description, ''), 'Mango Coconut er en fast skjeggbalm med ekte bivoks som gir skjegget form og hold gjennom dagen. Duften er søt, med mango i front og en mild kokostone, og den blekner raskt etter påføring. Inneholder sheasmør, bivoks, lanolin og en blanding av oljer som jojoba, argan og mandel. Balmen må varmes mellom fingrene før bruk.'), benefits = array['Bivoks gir sterk styling og hold','Holder skjegget på plass hele dagen','Søt, fruktig duft som ikke blir påtrengende','Uten konserveringsmidler']::text[], recommended_for = 'For deg med middels til langt skjegg som vil ha kontroll og liker en søt, fruktig duft.', how_to_use = 'Løsne overflaten med en negl, og varm en liten mengde mellom fingrene i ca. 10 sekunder. Arbeid den inn i skjegget, ikke ned i huden.', size_label = '50 ml', hold_level = null, shine_level = null, related_slugs = array['beard-monkey-beard-comb','graabein-beard-oil-rum-and-spice']::text[], web_name = null, content_review = false, content_note = null, content_source = 'https://www.graabein-skjegg.no/produkt/graabein-skjeggbalm-mango-coconut'
 where name = 'Graabein - Beard Balm Mango Coconut' and price_nok = 299.0 and slug is null;
update products set slug = 'graabein-beard-oil-rum-and-spice', brand = 'Graabein', category = 'Skjegg', short_description = 'Norsk skjeggolje med krydret appelsinduft som gir mykt skjegg og motvirker kløe og flass.', description = coalesce(nullif(description, ''), 'Rum and Spice er en skjeggolje fra Graabein som gir et mykt skjegg og motvirker kløe og flass. Duften er krydret og frisk, med appelsin og milde krydder. Inneholder tistelolje, druekjerneolje, mandelolje, jojobaolje, arganolje og vitamin E. Flasken har pumpe, så du får en jevn dose hver gang.'), benefits = array['Gjør skjegget mykere','Motvirker kløe og flass','Krydret og frisk duft','Pumpe som gir jevn dose og lekker ikke i veska']::text[], recommended_for = 'For alle skjeggtyper, særlig hvis skjegget er tørt eller huden under klør.', how_to_use = 'Pump ut noen dråper i hånden, gni lett mellom håndflatene og fordel i skjegget og ned mot huden.', size_label = '30 ml', hold_level = null, shine_level = null, related_slugs = array['graabein-skin-and-beard-softener-rum-spice','beard-monkey-beard-comb']::text[], web_name = null, content_review = false, content_note = null, content_source = 'https://www.graabein-skjegg.no/produkt/graabein-skjeggolje-rum-and-spice'
 where name = 'Graabein - Beard oil Rum and Spice' and price_nok = 299.0 and slug is null;
update products set slug = 'graabein-beard-oil-villmark', brand = 'Graabein', category = 'Skjegg', short_description = 'Norsk skjeggolje med kraftig duft av gran og skog som mykner skjegget og demper kløe.', description = coalesce(nullif(description, ''), 'Villmark er en skjeggolje med tydelig duft av norsk skog: gran på toppen, lavendel i midten og sandeltre i bunnen. Den mykner skjegget og demper kløe og tørr hud. Inneholder tistelolje, druekjerneolje, mandelolje, jojobaolje, arganolje og vitamin E. Flasken har pumpe som gir lik dose hver gang.'), benefits = array['Gjør skjegget mykt','Demper kløe, flass og tørr hud','Kraftig skogsduft av gran, lavendel og sandeltre','Pumpe med lokk som hindrer lekkasje']::text[], recommended_for = 'For alle skjeggtyper, og for deg som liker en kraftigere, skogaktig duft.', how_to_use = 'Pump ut noen dråper i hånden, gni lett mellom håndflatene og fordel i skjegget og ned mot huden.', size_label = '30 ml', hold_level = null, shine_level = null, related_slugs = array['graabein-villmark-beard-balm-30-ml','graabein-skin-and-beard-softener-villmark']::text[], web_name = null, content_review = false, content_note = null, content_source = 'https://www.graabein-skjegg.no/produkt/graabein-skjeggolje-villmark'
 where name = 'Graabein - Beard oil Villmark' and price_nok = 299.0 and slug is null;
update products set slug = 'graabein-skin-and-beard-softener-bris', brand = 'Graabein', category = 'Skjegg', short_description = 'Lett krem for skjegg og hud uten tilsatt duft som myker opp uten å fette.', description = coalesce(nullif(description, ''), 'Skin and Beard Softener er en vannløselig krem som ligger mellom skjeggolje og skjeggbalm. Den mykgjør huden og fukter skjegget uten å gjøre det fett eller blankt, og gir litt form uten bivoks. Bris er uten tilsatt duft, men de naturlige oljene kan ha en svak egenlukt. Inneholder blant annet mandelolje, avokadoolje, kakaosmør, sheasmør og vitamin E.'), benefits = array['Mykner skjegget og fukter huden under','Ikke fet eller blank','Lett formende effekt','Kan brukes i stedet for skjeggolje','Kan også brukes som fuktighetskrem i ansiktet']::text[], recommended_for = 'For deg som vil ha et mykt skjegg med lett tekstur og foretrekker et produkt uten tilsatt duft. Passer også om huden klør.', how_to_use = 'En fingertupp med krem holder for de fleste skjegg. Arbeid den gjennom skjegget og form med kam eller børste.', size_label = '50 ml', hold_level = null, shine_level = null, related_slugs = array['beard-monkey-beard-comb','beard-monkey-beard-shampoo-licorice']::text[], web_name = null, content_review = false, content_note = 'Produsenten oppgir ingen tilsatt duft; én kundeanmeldelse hos forhandler beskriver den som lett parfymert.', content_source = 'https://j-kshop.no/products/graabein-skin-and-beard-softener'
 where name = 'Graabein - Skin and Beard Softener Bris' and price_nok = 299.0 and slug is null;
