update products set slug = 'graabein-villmark-beard-balm-30-ml', brand = 'Graabein', category = 'Skjegg', short_description = 'Graabeins sterkeste skjeggbalm, med bivoks og skogsduft av gran, for kraftig hold.', description = coalesce(nullif(description, ''), 'Villmark er den sterkeste balmen i Graabein-serien, men fortsatt skånsom mot huden. Den bygger på Lysning-oppskriften med gran på toppen, og dufter av gran, lavendel og sandeltre. Inneholder sheasmør, bivoks, lanolin og en blanding av oljer som jojoba, argan og mandel. Ekte bivoks gir fast konsistens og hold som varer hele dagen.'), benefits = array['Graabeins sterkeste balm','Bivoks gir sterk styling og hold','Skogsduft av gran, lavendel og sandeltre','Kan blandes med skjeggolje']::text[], recommended_for = 'For middels til lange eller strie skjegg som trenger god kontroll.', how_to_use = 'Løsne overflaten med en negl, og varm en liten mengde mellom fingrene i ca. 10 sekunder. Arbeid den inn i skjegget, ikke ned i huden.', size_label = null, hold_level = null, shine_level = null, related_slugs = array['graabein-beard-oil-villmark','beard-monkey-beard-comb']::text[], web_name = null, content_review = true, content_note = 'Produktnavnet sier 30 ml, men produsentens side oppgir 50 ml for Villmark-balmen. Sjekk størrelsen på varen på lager.', content_source = 'https://www.graabein-skjegg.no/produkt/graabein-skjeggbalm-villmark'
