update products set slug = 'matrix-curl-can-dream-cream', brand = 'Matrix', category = 'Hårpleie', short_description = 'Leave-in krem med manukahonning som gir fukt og definisjon til krøller uten flak eller stivhet.', description = coalesce(nullif(description, ''), 'A Curl Can Dream Moisturizing Cream er en leave-in krem for bølger, krøller og tette krøller. Den inneholder manukahonningekstrakt og oljer av avokado, solsikke og camelina, og gir fukt og tydelig krøllmønster uten flak eller stiv finish. Formelen er uten silikoner, parabener og mineralolje.'), benefits = array['Gir fukt og definerer krøllene','Ingen flak eller stiv finish','Med manukahonning og avokadoolje','Uten silikoner, parabener og mineralolje','Kan brukes daglig']::text[], recommended_for = 'For bølget, krøllete og tett krøllete hår (type 2A–4C). Bruk mindre på fint hår og mer på tykt hår.', how_to_use = 'Fordel i dryppvått hår fra rot til tupp, seksjon for seksjon, og skrunsj. Følg gjerne opp med Light Hold Gel, og lufttørk eller bruk diffuser.', size_label = '500 ml', hold_level = null, shine_level = null, related_slugs = array['matrix-curl-can-dream-gel','matrix-curl-can-dream-mask']::text[], web_name = null, content_review = false, content_note = null, content_source = 'https://www.matrix.com/professional/products/hair-care/a-curl-can-dream/a-curl-can-dream-moisturizing-cream'
