update products set slug = 'matrix-curl-can-dream-gel', brand = 'Matrix', category = 'Styling', short_description = 'Lett gelé med manukahonning som definerer krøller uten å bli stiv eller flasse.', description = coalesce(nullif(description, ''), 'A Curl Can Dream Light Hold Gel definerer bølger og krøller og hjelper håret å holde på fukten. Den inneholder manukahonningekstrakt og er laget for å legges over A Curl Can Dream-kremen uten å flasse. Holdet er lett til middels, og blir sterkere jo mer du bruker. Formelen er uten silikoner, parabener og alkohol.'), benefits = array['Definerer bølger og krøller','Lett til middels hold som kan bygges opp','Lager seg over krøllkremen uten flak','Uten silikoner, parabener og alkohol']::text[], recommended_for = 'For bølget, krøllete og tett krøllete hår (type 2A–4C) som trenger definisjon og litt hold.', how_to_use = 'Påfør etter krøllkremen i vått hår, mindre i fint hår og mer i tykt hår. Lufttørk eller bruk diffuser.', size_label = null, hold_level = 2, shine_level = null, related_slugs = array['matrix-curl-can-dream-cream','matrix-curl-can-dream-mask']::text[], web_name = null, content_review = true, content_note = 'Størrelse ikke oppgitt i teksten på produsentens side (bildene antyder 200 ml). Glans ikke oppgitt.', content_source = 'https://www.matrix.com/professional/products/hair-care/a-curl-can-dream-light-hold-gel'
