-- ---------- 3) Nettordrer ----------
create table if not exists online_orders (
  id              uuid primary key default gen_random_uuid(),
  order_no        bigint generated always as identity,
  created_at      timestamptz not null default now(),
  access_token    uuid not null default gen_random_uuid(),
  customer_id     uuid references customers(id) on delete set null,
  name            text not null,
  email           text not null,
  phone           text,
  delivery        text not null default 'pickup',   -- pickup | ship
  address         text,
  postal_code     text,
  city            text,
  subtotal_nok    numeric(10,2) not null default 0,
  discount_nok    numeric(10,2) not null default 0,
  shipping_nok    numeric(10,2) not null default 0,
  total_nok       numeric(10,2) not null default 0,
  member_tier     text,
  payment_method  text not null default 'vipps',   -- vipps | card | pay_at_pickup
  payment_status  text not null default 'pending',  -- pending | authorized | paid | failed | cancelled | refunded
  status          text not null default 'new',      -- new | ready | picked_up | shipped | cancelled
  vipps_reference text,
  tracking_no     text,
  note            text,
  sale_id         uuid references sales(id) on delete set null,
  confirmed_at    timestamptz,
  ready_at        timestamptz,
  completed_at    timestamptz,
  cancelled_at    timestamptz
);

do $$ begin
  alter table online_orders add constraint online_orders_values_check check (
    delivery in ('pickup', 'ship')
    and payment_method in ('vipps', 'card', 'pay_at_pickup')
    and payment_status in ('pending', 'authorized', 'paid', 'failed', 'cancelled', 'refunded')
    and status in ('new', 'ready', 'picked_up', 'shipped', 'cancelled'));
exception when duplicate_object then null; end $$;

create index if not exists online_orders_created_idx on online_orders (created_at desc);
create index if not exists online_orders_status_idx on online_orders (status);

create table if not exists online_order_items (
  id             uuid primary key default gen_random_uuid(),
  order_id       uuid not null references online_orders(id) on delete cascade,
  product_id     uuid references products(id) on delete set null,
  name           text not null,
  unit_price_nok numeric(10,2) not null,
  qty            int not null check (qty > 0),
  line_total_nok numeric(10,2) not null
);
create index if not exists online_order_items_order_idx on online_order_items (order_id);

alter table online_orders enable row level security;
alter table online_order_items enable row level security;
drop policy if exists online_orders_shop on online_orders;
create policy online_orders_shop on online_orders for all to authenticated
  using (is_shop_or_admin()) with check (is_shop_or_admin());
drop policy if exists online_order_items_shop on online_order_items;
create policy online_order_items_shop on online_order_items for all to authenticated
  using (is_shop_or_admin()) with check (is_shop_or_admin());
revoke all on online_orders, online_order_items from anon;

-- Offentlige butikk-innstillinger (frakt osv.).
create or replace function webshop_settings()
returns json
language sql stable security definer set search_path = public as $$
  select coalesce((select value::json from settings where key = 'webshop'),
                  '{"live": false, "shipping_nok": 79, "free_over_nok": 599, "pickup": true, "ship": true, "pay_at_pickup": true}'::json);
$$;
grant execute on function webshop_settings() to anon, authenticated;

-- Opprett ordre. Pris, lager, frakt og kundeklubb-rabatt avgjøres HER
-- (aldri av nettleseren). Lageret reserveres med en gang.
create or replace function create_online_order(
  p_items    jsonb,          -- [{"id": uuid, "qty": n}]
  p_customer jsonb,          -- {"name","email","phone"}
  p_delivery text,           -- pickup | ship
  p_address  jsonb,          -- {"address","postal_code","city"} (ship)
  p_payment  text,           -- vipps | card | pay_at_pickup
  p_token    uuid default null,   -- innlogget kunde (portal-token)
  p_note     text default null
) returns json
language plpgsql security definer set search_path = public as $$
declare
  v_cfg json := webshop_settings();
  v_order uuid; v_no bigint; v_tok uuid;
  v_item jsonb; v_prod record; v_qty int; v_new int;
  v_sub numeric(10,2) := 0; v_disc numeric(10,2) := 0; v_ship numeric(10,2) := 0;
  v_cust uuid; v_name text; v_email text; v_phone text;
  v_tier membership_tiers; v_m record; v_pct numeric := 0;
begin
  v_name  := nullif(trim(p_customer->>'name'), '');
  v_email := lower(nullif(trim(p_customer->>'email'), ''));
  v_phone := nullif(trim(p_customer->>'phone'), '');
  if v_name is null or v_email is null then raise exception 'MISSING_CONTACT'; end if;
  if p_delivery not in ('pickup', 'ship') then raise exception 'BAD_DELIVERY'; end if;
  if p_payment not in ('vipps', 'card', 'pay_at_pickup') then raise exception 'BAD_PAYMENT'; end if;
  if p_payment = 'pay_at_pickup' and p_delivery <> 'pickup' then raise exception 'BAD_PAYMENT'; end if;
  if p_delivery = 'ship' and (
       coalesce(trim(p_address->>'address'), '') = ''
       or coalesce(trim(p_address->>'postal_code'), '') !~ '^\d{4}$'
       or coalesce(trim(p_address->>'city'), '') = '') then
    raise exception 'BAD_ADDRESS';
  end if;
  if coalesce(jsonb_array_length(p_items), 0) = 0 then raise exception 'EMPTY'; end if;

  -- Kunde: innlogget kunde først, ellers e-post/telefon, ellers ny.
  if p_token is not null then
    select id into v_cust from customers where portal_token = p_token limit 1;
  end if;
  if v_cust is null then
    select id into v_cust from customers where lower(trim(email)) = v_email limit 1;
  end if;
  if v_cust is null and v_phone is not null then
    select id into v_cust from customers
     where regexp_replace(coalesce(phone, ''), '\s', '', 'g') = regexp_replace(v_phone, '\s', '', 'g') limit 1;
  end if;
  if v_cust is null then
    insert into customers (full_name, email, phone, source)
    values (v_name, v_email, v_phone, 'Nettbutikk') returning id into v_cust;
  end if;

  -- Kundeklubb-rabatt på produkter: bare når kunden er innlogget.
  if p_token is not null then
    begin
      select * into v_m from customer_membership(v_cust) limit 1;
      select * into v_tier from membership_tiers where id = v_m.tier_id;
      v_pct := coalesce(v_tier.product_discount_pct, 0);
    exception when others then v_pct := 0;
    end;
  end if;

  insert into online_orders (customer_id, name, email, phone, delivery, address, postal_code, city,
                             payment_method, note, member_tier)
  values (v_cust, v_name, v_email, v_phone, p_delivery,
          case when p_delivery = 'ship' then trim(p_address->>'address') end,
          case when p_delivery = 'ship' then trim(p_address->>'postal_code') end,
          case when p_delivery = 'ship' then trim(p_address->>'city') end,
          p_payment, nullif(left(coalesce(p_note, ''), 500), ''),
          case when v_pct > 0 then v_tier.name end)
  returning id, order_no, access_token into v_order, v_no, v_tok;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_qty := least(20, greatest(1, coalesce((v_item->>'qty')::int, 1)));
    select id, coalesce(web_name, name) as name, price_nok, stock, is_gift_card into v_prod
      from products
     where id = (v_item->>'id')::uuid and active = true and coalesce(online, true)
       and not is_gift_card   -- gavekort selges i salongen (kode lages i kassa)
     for update;
    if not found then raise exception 'NOT_FOUND'; end if;
    if not v_prod.is_gift_card and v_prod.stock < v_qty then
      raise exception 'OUT_OF_STOCK:%', v_prod.name;
    end if;
    insert into online_order_items (order_id, product_id, name, unit_price_nok, qty, line_total_nok)
    values (v_order, v_prod.id, v_prod.name, v_prod.price_nok, v_qty, v_prod.price_nok * v_qty);
    v_sub := v_sub + v_prod.price_nok * v_qty;
    if not v_prod.is_gift_card then
      update products set stock = stock - v_qty where id = v_prod.id returning stock into v_new;
      insert into stock_movements (product_id, delta, reason, note, new_stock)
      values (v_prod.id, -v_qty, 'nettordre', 'Ordre #' || v_no, v_new);
    end if;
  end loop;

  v_disc := round(v_sub * v_pct / 100);
  if p_delivery = 'ship' and (v_sub - v_disc) < coalesce((v_cfg->>'free_over_nok')::numeric, 599) then
    v_ship := coalesce((v_cfg->>'shipping_nok')::numeric, 79);
  end if;

  update online_orders
     set subtotal_nok = v_sub, discount_nok = v_disc, shipping_nok = v_ship,
         total_nok = v_sub - v_disc + v_ship,
         confirmed_at = case when p_payment = 'pay_at_pickup' then now() end
   where id = v_order;

  return json_build_object('id', v_order, 'order_no', v_no, 'token', v_tok,
                           'total_nok', v_sub - v_disc + v_ship);
end $$;

revoke execute on function create_online_order(jsonb, jsonb, text, jsonb, text, uuid, text) from public;
grant  execute on function create_online_order(jsonb, jsonb, text, jsonb, text, uuid, text) to anon, authenticated;

-- Kunden ser sin egen ordre (bekreftelsessiden) med ordre-id + hemmelig token.
create or replace function online_order_public(p_order uuid, p_token uuid)
returns json
language sql stable security definer set search_path = public as $$
  select json_build_object(
    'id', o.id, 'order_no', o.order_no, 'created_at', o.created_at, 'name', o.name, 'email', o.email,
    'delivery', o.delivery, 'address', o.address, 'postal_code', o.postal_code, 'city', o.city,
    'subtotal_nok', o.subtotal_nok, 'discount_nok', o.discount_nok, 'shipping_nok', o.shipping_nok,
    'total_nok', o.total_nok, 'member_tier', o.member_tier, 'payment_method', o.payment_method,
    'payment_status', o.payment_status, 'status', o.status, 'tracking_no', o.tracking_no,
    'items', coalesce((select json_agg(json_build_object('name', i.name, 'qty', i.qty,
                         'unit_price_nok', i.unit_price_nok, 'line_total_nok', i.line_total_nok))
                         from online_order_items i where i.order_id = o.id), '[]'::json))
  from online_orders o where o.id = p_order and o.access_token = p_token;
$$;
revoke execute on function online_order_public(uuid, uuid) from public;
grant  execute on function online_order_public(uuid, uuid) to anon, authenticated;

-- Avbryt ordre og legg varene tilbake på lager (kassa, eller server ved
-- avbrutt Vipps-betaling via service-rollen).
create or replace function cancel_online_order(p_order uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare v_o online_orders; v_i record; v_new int;
begin
  if auth.role() <> 'service_role' and not is_shop_or_admin() then raise exception 'Ikke tilgang'; end if;
  select * into v_o from online_orders where id = p_order for update;
  if v_o.id is null or v_o.status = 'cancelled' then return; end if;
  if v_o.status in ('picked_up', 'shipped') then raise exception 'ALREADY_DONE'; end if;
  for v_i in select product_id, qty from online_order_items where order_id = p_order and product_id is not null loop
    update products set stock = stock + v_i.qty
     where id = v_i.product_id and not is_gift_card returning stock into v_new;
    if found then
      insert into stock_movements (product_id, delta, reason, note, new_stock)
      values (v_i.product_id, v_i.qty, 'nettordre avbrutt', 'Ordre #' || v_o.order_no, v_new);
    end if;
  end loop;
  update online_orders
     set status = 'cancelled', cancelled_at = now(),
         payment_status = case when payment_status in ('pending', 'authorized') then 'cancelled' else payment_status end
   where id = p_order;
end $$;
revoke execute on function cancel_online_order(uuid) from public, anon;
grant  execute on function cancel_online_order(uuid) to authenticated, service_role;

-- Utlevert / sendt: registrer ordren som salg (regnskap). Lageret er
-- allerede trukket da ordren ble laget, så det røres ikke her.
create or replace function complete_online_order(p_order uuid, p_payment_method text, p_tracking text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare v_o online_orders; v_sale uuid; v_i record;
begin
  if not is_shop_or_admin() then raise exception 'Ikke tilgang'; end if;
  select * into v_o from online_orders where id = p_order for update;
  if v_o.id is null then raise exception 'NOT_FOUND'; end if;
  if v_o.status in ('picked_up', 'shipped', 'cancelled') then raise exception 'ALREADY_DONE'; end if;

  insert into sales (booking_id, staff_id, customer_id, total_nok, payment_method)
  values (null, null, v_o.customer_id, v_o.total_nok, p_payment_method)
  returning id into v_sale;
  update sales set discount_nok = v_o.discount_nok where id = v_sale;

  for v_i in select * from online_order_items where order_id = p_order loop
    insert into sale_items (sale_id, kind, ref_id, description, quantity, price_nok)
    values (v_sale, 'product', v_i.product_id, v_i.name, v_i.qty, v_i.unit_price_nok);
  end loop;
  if v_o.shipping_nok > 0 then
    insert into sale_items (sale_id, kind, ref_id, description, quantity, price_nok)
    values (v_sale, 'shipping', null, 'Frakt', 1, v_o.shipping_nok);
  end if;
  insert into sale_payments (sale_id, method, amount) values (v_sale, p_payment_method, v_o.total_nok);
  if v_o.member_tier is not null and v_o.discount_nok > 0 then
    begin
      update sales set member_tier = v_o.member_tier, member_discount_nok = v_o.discount_nok where id = v_sale;
    exception when undefined_column then null;
    end;
  end if;

  update online_orders
     set status = case when delivery = 'ship' then 'shipped' else 'picked_up' end,
         payment_status = 'paid', sale_id = v_sale, completed_at = now(),
         tracking_no = coalesce(nullif(trim(p_tracking), ''), tracking_no)
   where id = p_order;
  return v_sale;
end $$;
revoke execute on function complete_online_order(uuid, text, text) from public, anon;
grant  execute on function complete_online_order(uuid, text, text) to authenticated;

notify pgrst, 'reload schema';
